/**
 * The release build must never be signed with the debug key.
 *
 * `plugins/withReleaseSigning.js` rewrites the generated `android/app/build.gradle`, and the thing
 * worth testing is not that it edits text -- it is that the edit cannot silently fail. Expo's
 * template is what the plugin anchors to, and `android/` is regenerated by every prebuild, so a
 * template change is the realistic way this breaks. The plugin throws when its anchors move; these
 * tests hold it to that, and check the patch against the real generated file when there is one.
 *
 * Written in JavaScript because the subject is a CommonJS config plugin; `tsconfig.json` only
 * includes `.ts`/`.tsx`, so this file is linted and run but not type-checked.
 */
const fs = require('fs');
const path = require('path');

const { patch } = require('../plugins/withReleaseSigning');

/** The part of Expo's template the plugin depends on, verbatim. */
const TEMPLATE = `apply plugin: "com.android.application"

def jscFlavor = 'io.github.react-native-community:jsc-android:2026004.+'

android {
    namespace 'com.kruegerco.silentsum'
    defaultConfig {
        versionCode 1
        versionName "0.1.0"
    }
    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }
    buildTypes {
        debug {
            signingConfig signingConfigs.debug
        }
        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug
            minifyEnabled enableMinifyInReleaseBuilds
        }
    }
}
`;

/** Everything inside `buildTypes { release { ... } }`, which is what must not use the debug key. */
function releaseBuildType(gradle) {
  const start = gradle.indexOf('buildTypes {');
  expect(start).toBeGreaterThan(-1);
  const at = gradle.indexOf('release {', start);
  expect(at).toBeGreaterThan(-1);
  return gradle.slice(at, gradle.indexOf('\n        }', at));
}

describe('withReleaseSigning', () => {
  it('stops the release build type using the debug key', () => {
    const release = releaseBuildType(patch(TEMPLATE));
    expect(release).not.toContain('signingConfigs.debug');
    expect(release).toContain(
      'signingConfig silentsumSigning != null ? signingConfigs.release : null',
    );
  });

  it('leaves the debug build type signed by the debug key', () => {
    const patched = patch(TEMPLATE);
    const debugBlock = patched.slice(
      patched.indexOf('buildTypes {'),
      patched.indexOf('release {', patched.indexOf('buildTypes {')),
    );
    expect(debugBlock).toContain('signingConfig signingConfigs.debug');
  });

  it('declares a release signing config fed from outside the repository', () => {
    const patched = patch(TEMPLATE);
    expect(patched).toContain('signingConfigs {');
    expect(patched).toContain('storeFile silentsumSigning.store');
    expect(patched).toContain("pick('storeFile', 'SILENTSUM_KEYSTORE_FILE')");
    // The properties file must be looked for OUTSIDE android/, which prebuild deletes.
    expect(patched).toContain('rootProject.projectDir.parentFile');
  });

  it('carries no credential of its own', () => {
    const patched = patch(TEMPLATE);
    // The only literal keystore material in the file stays the template's debug one.
    expect(patched.match(/storePassword\s+'[^']*'/g)).toEqual(["storePassword 'android'"]);
    expect(patched.match(/keyAlias\s+'[^']*'/g)).toEqual(["keyAlias 'androiddebugkey'"]);
  });

  it('fails a release task when nothing supplied credentials', () => {
    const patched = patch(TEMPLATE);
    expect(patched).toContain('gradle.taskGraph.whenReady');
    expect(patched).toContain('No Android release signing credentials.');
    // A release build must stop rather than fall back to anything.
    expect(patched).toContain("t.name.endsWith('Release')");
  });

  /**
   * EAS Build writes its own `android/app/eas-build.gradle` and applies it from build.gradle, so it
   * arrives with credentials this file cannot see. `android/` is git-ignored, which means EAS
   * regenerates it with prebuild and runs this same code -- so without standing down, the guard
   * above would refuse every EAS build for want of a key EAS already holds.
   */
  describe('on EAS Build', () => {
    it('detects the build environment', () => {
      expect(patch(TEMPLATE)).toContain(
        "def silentsumOnEas = System.getenv('EAS_BUILD') == 'true'",
      );
    });

    it('does not fail the build for missing local credentials', () => {
      expect(patch(TEMPLATE)).toContain('if (silentsumSigning == null && !silentsumOnEas) {');
    });

    it('assigns no release signingConfig, rather than assigning null over EAS’s own', () => {
      const release = releaseBuildType(patch(TEMPLATE));
      expect(release).toContain('if (!silentsumOnEas) {');
      // Still nothing that could reach for the debug key.
      expect(release).not.toContain('signingConfigs.debug');
    });
  });

  it('removes the template advice it has just acted on', () => {
    expect(patch(TEMPLATE)).not.toContain('Caution! In production');
  });

  it('is idempotent, so a re-run of prebuild cannot double-patch', () => {
    const once = patch(TEMPLATE);
    expect(patch(once)).toBe(once);
  });

  it('refuses a template whose signing lines have moved', () => {
    // One occurrence instead of two: the release block no longer says what the plugin expects, and
    // guessing would leave the release signed by the debug key.
    const moved = TEMPLATE.replace(
      '            signingConfig signingConfigs.debug\n            minifyEnabled',
      '            minifyEnabled',
    );
    expect(() => patch(moved)).toThrow(/template has changed/i);
  });

  it('refuses a template with no signingConfigs block', () => {
    const gutted = TEMPLATE.replace('signingConfigs {', 'somethingElse {');
    expect(() => patch(gutted)).toThrow(/template has changed/i);
  });

  const generated = path.join(__dirname, '..', 'android', 'app', 'build.gradle');
  const describeGenerated = fs.existsSync(generated) ? describe : describe.skip;

  // Skipped where `android/` has not been generated -- CI runs `npm ci && npm test` without it.
  describeGenerated('against the generated project', () => {
    it('patches the real build.gradle and removes the debug key from release', () => {
      const real = fs.readFileSync(generated, 'utf8');
      const patched = real.includes('SILENTSUM_RELEASE_SIGNING') ? real : patch(real);
      expect(releaseBuildType(patched)).not.toContain('signingConfigs.debug');
    });
  });
});
